import websocket

URL = "ws://web.chal.csaw.io:5000/websocket"

class DDP:
    def __init__(self, url=URL, timeout=30):
        self.ws = websocket.create_connection(url, timeout=timeout,
                header={"Origin": "http://web.chal.csaw.io:5000"})
        self.counter = 0
        self.msgs = []
        self.url = url
        self.ws.send(json.dumps({"msg": "connect", "version": "1",
                                 "support": ["1", "pre2", "pre1", "0"]}))
        r = self._read_until(lambda m: m.get("msg") in ("connected", "failed", "error"))
        if r.get("msg") != "connected":
            raise Exception("connect failed: %s" % r)
        self.session = r.get("session")

    def _read_until(self, pred, timeout=30):
        end = time.time() + timeout
        while time.time() < end:
            self.ws.settimeout(max(0.1, end - time.time()))
            try:
                data = self.ws.recv()
            except websocket.WebSocketTimeoutException:
                continue
            if not data:
                continue
            m = json.loads(data)
            if m.get("msg") == "ping":
                self.ws.send(json.dumps({"msg": "pong", "id": m.get("id")}))
                continue
            if pred(m):
                return m
            self.msgs.append(m)
        raise Exception("timeout waiting")

    def call(self, method, params=(), timeout=30):
        self.counter += 1
        mid = str(self.counter)
        self.ws.send(json.dumps({"msg": "method", "method": method,
                                 "params": list(params), "id": mid}))
        return self._read_until(lambda m: m.get("msg") == "result" and m.get("id") == mid, timeout)

    def sub(self, name, params=(), timeout=30):
        self.counter += 1
        mid = "s" + str(self.counter)
        self.ws.send(json.dumps({"msg": "sub", "name": name,
                                 "params": list(params), "id": mid}))
        return self._read_until(lambda m: m.get("msg") in ("ready", "nosub") and m.get("id") == mid, timeout)

    def close(self):
        try:
            self.ws.close()
        except Exception:
            pass


def call_once(method, params=()):
    d = DDP()
    try:
        r = d.call(method, params)
        return r
    finally:
        d.close()

